/**
 * Normaliza a questão para o formato bilíngue
 */
function getQText(q) {
    const lang = localStorage.getItem('pl300_lang') || 'pt';
    
    if (lang === 'pt') {
        return {
            question: q.question_pt ?? q.pergunta ?? q.question ?? '',
            options: q.options_pt ?? q.opcoes ?? q.options ?? [],
            explanation: q.explanation_pt ?? q.explicacao ?? q.explanation ?? '',
            answer: q.answer ?? q.correta
        };
    } else {
        return {
            question: q.question_en ?? q.question ?? q.pergunta ?? '',
            options: q.options_en ?? q.options ?? q.opcoes ?? [],
            explanation: q.explanation_en ?? q.explanation ?? q.explicacao ?? '',
            answer: q.answer ?? q.correta
        };
    }
}

